    await logJson(cwd, {
      stack: optionalBoolean(args.stack),
      all: optionalBoolean(args.all),
      reverse: optionalBoolean(args.reverse),
      prs: optionalBoolean(args.prs),
      ci: optionalBoolean(args.ci),
      overview,
